// Local stand-in for the podkrepi-bg NestJS API (+ Keycloak login, Ghost blog, image storage).
// Serves data from db.json (generated by seed.js) at http://localhost:5010/api/v1 and /ghost.
const http = require('http')
const fs = require('fs')
const path = require('path')
const crypto = require('crypto')
const { renderImage } = require('./images')

const PORT = +process.env.STUB_PORT || 5010
const db = JSON.parse(fs.readFileSync(path.join(__dirname, 'db.json'), 'utf8'))
const ME = db.persons.find((p) => p.id === db.me.personId)

const by = (arr, k = 'id') => Object.fromEntries(arr.map((x) => [x[k], x]))
const personById = by(db.persons)
const payById = by(db.payments)
const vaultById = by(db.vaults)
const typeById = by(db.campaignTypes)
const coordById = by(db.coordinators)
const orgById = by(db.organizers)
const benById = by(db.beneficiaries)
const campById = by(db.campaigns)
const fileById = by(db.campaignFiles.concat(db.newsFiles))
const PUBLIC_STATES = ['active', 'complete', 'partially_financed', 'paused', 'suspended']

// ------------------------------------------------------------ auth (Keycloak-like JWT)
const b64u = (o) => Buffer.from(JSON.stringify(o)).toString('base64url')
function makeToken() {
  const now = Math.floor(Date.now() / 1000)
  const payload = {
    exp: now + 30 * 86400, iat: now, jti: crypto.randomUUID(), iss: 'http://localhost:5010/realms/webapp', aud: 'account', sub: ME.keycloakId, typ: 'Bearer', azp: 'jwt-headless', session_state: crypto.randomUUID(), acr: '1', sid: crypto.randomUUID(),
    'allowed-origins': ['http://localhost:4486'],
    realm_access: { roles: ['offline_access', 'default-roles-webapp', 'uma_authorization', 'view-supporters', 'view-contact-requests', 'team-support'] },
    resource_access: { account: { roles: ['manage-account', 'manage-account-links', 'view-profile', 'account-view-supporters', 'account-view-contact-requests'] } },
    scope: 'openid email profile', email_verified: true, name: `${ME.firstName} ${ME.lastName}`, preferred_username: ME.email, given_name: ME.firstName, family_name: ME.lastName, email: ME.email, locale: 'bg', theme: 'light', company: '',
  }
  return `${b64u({ alg: 'RS256', typ: 'JWT', kid: 'local-stub' })}.${b64u(payload)}.${crypto.randomBytes(32).toString('base64url')}`
}
const authResponse = () => ({ accessToken: makeToken(), refreshToken: makeToken(), expires: String(30 * 86400) })

// ------------------------------------------------------------ shapes
const personLite = (p) => (p ? { id: p.id, firstName: p.firstName, lastName: p.lastName, email: p.email, company: p.company ?? null } : null)
function summaryFor(c) {
  const v = vaultById[c._vaultId]
  const donors = new Set()
  let n = 0
  for (const d of donationsByCampaign[c.id] || []) if (payById[d.paymentId].status === 'succeeded') { n++; donors.add(d._realPersonId || d.id) }
  return { reachedAmount: v.amount, currentAmount: v.amount - v.withdrawnAmount, blockedAmount: v.blockedAmount, withdrawnAmount: v.withdrawnAmount, guaranteedAmount: 0, donors: n }
}
const donationsByCampaign = {}
for (const d of db.donations) (donationsByCampaign[d._campaignId] ||= []).push(d)
function campaignShape(c, full = false) {
  const t = typeById[c.campaignTypeId]
  const b = benById[c.beneficiaryId]
  const co = coordById[c.coordinatorId]
  const o = orgById[c.organizerId]
  const { _fill, _vaultId, _cityName, ...base } = c
  const out = {
    ...base,
    campaignType: { id: t.id, name: t.name, slug: t.slug, category: t.category },
    category: t.category,
    beneficiary: { id: b.id, type: b.type, publicData: b.publicData, person: b.person, company: b.company, countryCode: 'BG', city: b.city, description: b.description },
    coordinator: { id: co.id, person: personLite(co.person) },
    organizer: o ? { id: o.id, person: personLite(o.person) } : null,
    summary: summaryFor(c),
    campaignFiles: db.campaignFiles.filter((f) => f.campaignId === c.id).map(({ image, ...f }) => f),
    vaults: [{ ...vaultById[c._vaultId] }],
    defaultVault: c._vaultId,
  }
  if (full) {
    out.campaignNews = db.campaignNews.filter((n) => n.campaignId === c.id && n.state === 'published').sort((a, b) => b.publishedAt.localeCompare(a.publishedAt)).slice(0, 3).map((n) => newsShape(n))
    out.incomingTransfers = db.transfers.filter((t) => t.targetCampaignId === c.id && t.status === 'succeeded').map((t) => ({ amount: t.amount }))
  }
  return out
}
function newsShape(n) {
  const c = campById[n.campaignId]
  return { ...n, newsFiles: n.newsFiles.map(({ image, ...f }) => f), campaign: { id: c.id, title: c.title, state: c.state, slug: c.slug } }
}
function donationShape(d, opts = {}) {
  const p = payById[d.paymentId]
  const per = d.personId ? personById[d.personId] : null
  const c = campById[d._campaignId]
  return {
    id: d.id, type: d.type, paymentId: d.paymentId, targetVaultId: d.targetVaultId, createdAt: d.createdAt, updatedAt: d.updatedAt, amount: d.amount, currency: d.currency, personId: d.personId, billingEmail: d.billingEmail,
    person: per ? { id: per.id, firstName: per.firstName, lastName: per.lastName, email: per.email, company: per.company } : null,
    metadata: { name: d._anon ? '' : p.billingName },
    payment: { ...p },
    status: p.status, provider: p.provider,
    targetVault: { id: d.targetVaultId, name: vaultById[d.targetVaultId].name, campaign: { id: c.id, slug: c.slug, title: c.title } },
    affiliate: null,
  }
}
function paginate(items, q, idxKey = 'pageindex', sizeKey = 'pagesize') {
  const pi = parseInt(q.get(idxKey) ?? q.get('pageIndex') ?? '0') || 0
  const ps = parseInt(q.get(sizeKey) ?? q.get('pageSize') ?? '10') || 10
  return { items: items.slice(pi * ps, pi * ps + ps), total: items.length }
}
const valid = (v) => v && v !== 'undefined' && v !== 'null' && v !== ''
const desc = (k) => (a, b) => String(b[k]).localeCompare(String(a[k]))

function filterDonations(q, list) {
  let items = list
  if (valid(q.get('campaignId'))) items = items.filter((d) => d._campaignId === q.get('campaignId'))
  if (valid(q.get('status'))) items = items.filter((d) => payById[d.paymentId].status === q.get('status'))
  if (valid(q.get('provider'))) items = items.filter((d) => payById[d.paymentId].provider === q.get('provider'))
  if (valid(q.get('paymentId'))) items = items.filter((d) => d.paymentId === q.get('paymentId'))
  if (valid(q.get('from'))) items = items.filter((d) => d.createdAt >= new Date(q.get('from')).toISOString())
  if (valid(q.get('to'))) items = items.filter((d) => d.createdAt <= new Date(q.get('to')).toISOString())
  if (valid(q.get('minAmount'))) items = items.filter((d) => d.amount >= +q.get('minAmount') * 100)
  if (valid(q.get('maxAmount'))) items = items.filter((d) => d.amount <= +q.get('maxAmount') * 100)
  if (valid(q.get('search'))) {
    const s = q.get('search').toLowerCase()
    items = items.filter((d) => (payById[d.paymentId].billingName + ' ' + d.billingEmail).toLowerCase().includes(s))
  }
  const sortBy = q.get('sortBy')
  if (sortBy === 'amount') items = [...items].sort((a, b) => (q.get('sortOrder') === 'asc' ? a.amount - b.amount : b.amount - a.amount))
  else items = [...items].sort(desc('createdAt'))
  return items
}

function groupedStats(campaignId, groupBy) {
  const m = {}
  for (const d of donationsByCampaign[campaignId] || []) {
    if (payById[d.paymentId].status !== 'succeeded') continue
    const dt = new Date(d.createdAt)
    let key
    if (groupBy === 'month') key = new Date(Date.UTC(dt.getUTCFullYear(), dt.getUTCMonth(), 1)).toISOString()
    else if (groupBy === 'week') { const w = new Date(dt); w.setUTCDate(dt.getUTCDate() - dt.getUTCDay()); key = w.toISOString().slice(0, 10) + 'T00:00:00.000Z' }
    else key = dt.toISOString().slice(0, 10) + 'T00:00:00.000Z'
    m[key] ||= { sum: 0, count: 0, date: key }
    m[key].sum += d.amount
    m[key].count++
  }
  return Object.values(m).sort((a, b) => a.date.localeCompare(b.date))
}

// ------------------------------------------------------------ routing
const routes = []
const get = (re, fn) => routes.push(['GET', re, fn])
const any = (re, fn) => routes.push(['*', re, fn])

const myDonations = () => db.donations.filter((d) => d._realPersonId === ME.id).sort(desc('createdAt'))
const meShape = () => ({
  ...ME,
  company: null,
  coordinators: { id: db.coordinators[0].id, _count: { campaigns: 0 } },
  organizer: { id: db.organizers[0].id, _count: { campaigns: db.campaigns.filter((c) => c.organizerId === db.organizers[0].id).length } },
  beneficiaries: [],
})

get(/^\/campaign\/list$/, () => db.campaigns.filter((c) => PUBLIC_STATES.includes(c.state)).map((c) => campaignShape(c)))
get(/^\/campaign\/list-all$/, () => db.campaigns.map((c) => campaignShape(c)))
get(/^\/campaign\/get-user-campaigns$/, () => db.campaigns.filter((c) => c.organizerId === db.organizers[0].id).map((c) => campaignShape(c)))
get(/^\/campaign\/user-donations-campaigns$/, () => {
  const ids = new Set(myDonations().map((d) => d._campaignId))
  return db.campaigns.filter((c) => ids.has(c.id)).map((c) => campaignShape(c))
})
get(/^\/campaign\/news$/, (m, q) => newsPage(db.campaignNews, q))
get(/^\/campaign\/([^/]+)\/news$/, (m, q) => {
  const c = db.campaigns.find((x) => x.slug === m[1])
  if (!c) return [404, { message: 'Not found' }]
  const p = newsPage(db.campaignNews.filter((n) => n.campaignId === c.id), q)
  return { campaign: { title: c.title, slug: c.slug, campaignNews: p.articles }, pagination: p.pagination }
})
function newsPage(list, q) {
  const page = Math.max(1, parseInt(q.get('page') || '1'))
  const pub = list.filter((n) => n.state === 'published').sort(desc('publishedAt'))
  const per = 4
  const totalPages = Math.max(1, Math.ceil(pub.length / per))
  const articles = pub.slice((page - 1) * per, page * per).map(newsShape)
  return { articles, pagination: { currentPage: page, nextPage: page < totalPages ? page + 1 : null, prevPage: page > 1 ? page - 1 : null, totalPages } }
}
get(/^\/campaign\/byId\/([^/]+)$/, (m) => (campById[m[1]] ? campaignShape(campById[m[1]], true) : [404, { message: 'Not found' }]))
get(/^\/campaign\/donations\/([^/]+)$/, (m) => (donationsByCampaign[m[1]] || []).map((d) => donationShape(d)))
get(/^\/campaign\/([^/]+)\/expenses(\/approved)?$/, (m) => {
  const c = db.campaigns.find((x) => x.slug === m[1])
  return db.expenses.filter((e) => e._campaignId === c?.id && (!m[2] || e.status === 'approved'))
})
get(/^\/campaign\/([^/]+)\/can-edit$/, () => true)
get(/^\/campaign\/([^/]+)$/, (m) => {
  const c = db.campaigns.find((x) => x.slug === m[1])
  return c ? { campaign: campaignShape(c, true) } : [404, { message: 'Not found' }]
})
get(/^\/campaign-type\/list$|^\/campaign-types\/?$/, () => db.campaignTypes)
get(/^\/campaign-types\/([^/]+)$/, (m) => db.campaignTypes.find((t) => t.id === m[1]))
get(/^\/campaign-file\/([^/]+)$/, (m) => ({ __image: fileById[m[1]]?.image || { kind: 'others', seedIdx: 1, role: 'gallery' } }))
get(/^\/campaign-news-file\/([^/]+)$/, (m) => ({ __image: fileById[m[1]]?.image || { kind: 'others', seedIdx: 2, role: 'gallery' } }))
get(/^\/blog-image\/(\d+)$/, (m) => ({ __image: { kind: ['charity', 'others', 'education', 'others', 'events', 'charity', 'disasters', 'others', 'medical', 'charity', 'education', 'environment'][+m[1] % 12], seedIdx: 300 + +m[1], role: 'blog' } }))

get(/^\/campaign-news\/list-all$/, () => db.campaignNews.map((n) => ({ ...newsShape(n), campaign: { title: campById[n.campaignId].title } })))
get(/^\/campaign-news\/byId\/([^/]+)$/, (m) => newsShape(db.campaignNews.find((n) => n.id === m[1])))
get(/^\/campaign-news\/([^/]+)\/list$/, (m) => db.campaignNews.filter((n) => campById[n.campaignId].slug === m[1]).map(newsShape))
get(/^\/campaign-news\/([^/]+)$/, (m) => { const n = db.campaignNews.find((x) => x.slug === m[1]); return n ? newsShape(n) : [404, {}] })

// donations
get(/^\/donation\/listPublic\/?$/, (m, q) => {
  const items = filterDonations(q, db.donations)
  const pi = parseInt(q.get('pageindex') || '0') || 0, ps = parseInt(q.get('pagesize') || '5') || 5
  return { items: items.slice(pi * ps, pi * ps + ps).map((d) => { const s = donationShape(d); if (d._anon) { s.person = null; s.metadata = { name: '' } } return s }), total: items.length }
})
get(/^\/donation\/list$/, (m, q) => { const p = paginate(filterDonations(q, db.donations), q); return { items: p.items.map((d) => donationShape(d)), total: p.total } })
get(/^\/donation\/payments$/, (m, q) => {
  let items = db.payments
  if (valid(q.get('status'))) items = items.filter((p) => p.status === q.get('status'))
  if (valid(q.get('provider'))) items = items.filter((p) => p.provider === q.get('provider'))
  if (valid(q.get('search'))) items = items.filter((p) => (p.billingName + p.billingEmail).toLowerCase().includes(q.get('search').toLowerCase()))
  items = [...items].sort(desc('createdAt'))
  const p = paginate(items, q)
  const dByPay = {}
  for (const d of db.donations) dByPay[d.paymentId] = d
  return { items: p.items.map((x) => ({ ...x, donations: [donationShape(dByPay[x.id])] })), total: p.total }
})
get(/^\/donation\/payments\/([^/]+)$/, (m) => { const p = payById[m[1]]; return p ? { ...p, donations: db.donations.filter((d) => d.paymentId === p.id).map((d) => donationShape(d)) } : [404, {}] })
get(/^\/donation\/user-donations$/, () => {
  const mine = myDonations()
  return { donations: mine.map((d) => ({ ...donationShape(d), personId: ME.id })), total: mine.filter((d) => payById[d.paymentId].status === 'succeeded').reduce((s, d) => s + d.amount, 0) }
})
get(/^\/donation\/user\/([^/]+)$/, (m) => { const d = db.donations.find((x) => x.id === m[1]); return d ? { ...donationShape(d), person: meShape() } : [404, {}] })
get(/^\/donation\/donors-count$/, () => ({ count: new Set(db.donations.map((d) => d._realPersonId || d.billingEmail)).size + 41870 }))
get(/^\/donation\/money$/, () => ({ total: db.vaults.reduce((s, v) => s + v.amount, 0) + 412345600 }))
get(/^\/donation\/payment-intent$/, () => [404, {}])
get(/^\/donation\/list-with-wishes\/([^/]+)$/, (m, q) => {
  const ws = db.wishes.filter((w) => w.campaignId === m[1]).sort(desc('createdAt'))
  const p = paginate(ws, q)
  const dById = by(db.donations)
  return { items: p.items.map((w) => ({ ...donationShape(dById[w.donationId]), donationWish: { id: w.id, message: w.message, createdAt: w.createdAt } })), total: p.total }
})
get(/^\/donation\/([0-9a-f-]{36})$/, (m) => { const d = db.donations.find((x) => x.id === m[1]); return d ? donationShape(d) : [404, {}] })
get(/^\/donation-wish\/list\/([^/]+)$/, (m, q) => {
  const ws = db.wishes.filter((w) => w.campaignId === m[1]).sort(desc('createdAt'))
  const p = paginate(ws, q)
  return { items: p.items.map((w) => { const per = w.personId && !w._anon ? personById[w.personId] : null; return { ...w, person: per ? { firstName: per.firstName, lastName: per.lastName } : null, donation: { amount: db.donations.find((d) => d.id === w.donationId)?.amount, type: 'donation', metadata: { name: '' } } } }), total: p.total }
})
get(/^\/statistics\/donations\/([^/]+)$/, (m, q) => groupedStats(m[1], q.get('groupBy') || 'day'))
get(/^\/statistics\/unique-donations\/([^/]+)$/, (m) => {
  const cnt = {}
  for (const d of donationsByCampaign[m[1]] || []) if (payById[d.paymentId].status === 'succeeded') cnt[d.amount] = (cnt[d.amount] || 0) + 1
  return Object.entries(cnt).map(([amount, count]) => ({ amount: +amount, count })).sort((a, b) => b.count - a.count)
})
get(/^\/statistics\/hourly-donations\/([^/]+)$/, (m) => {
  const h = Array.from({ length: 24 }, (_, hour) => ({ hour, count: 0 }))
  for (const d of donationsByCampaign[m[1]] || []) h[(new Date(d.createdAt).getUTCHours() + 2) % 24].count++
  return h
})
get(/^\/stripe\/prices(\/single|\/recurring)?$/, (m) => {
  const amts = [500, 1000, 2000, 5000, 10000, 20000]
  return amts.map((a, i) => ({ id: `price_1Pk${i}local${a}`, object: 'price', active: true, currency: 'eur', unit_amount: a, recurring: m[1] === '/recurring' ? { interval: 'month' } : null, type: m[1] === '/recurring' ? 'recurring' : 'one_time', metadata: { title: `${a / 100} евро` } }))
})
get(/^\/recurring-donation\/user-donations$/, () => db.recurringDonations.filter((r) => r.personId === ME.id).map(rdShape))
get(/^\/recurring-donation\/list$/, () => db.recurringDonations.map(rdShape))
get(/^\/recurring-donation\/([^/]+)$/, (m) => rdShape(db.recurringDonations.find((r) => r.id === m[1])))
function rdShape(r) {
  const c = campById[r.campaignId]
  return { ...r, sourceVault: { ...vaultById[r.vaultId], campaign: { id: c.id, title: c.title, slug: c.slug } }, campaign: { id: c.id, title: c.title, slug: c.slug } }
}

